module TopModule (
    input  [7:0] a,
    input  [7:0] b,
    output [7:0] s,
    output       overflow
);

    // Internal signal for the 9-bit sum (to capture the carry out of bit 7)
    wire [8:0] sum;

    // Perform the addition. The extra MSB captures the carry out of bit 7.
    assign sum = {1'b0, a} + {1'b0, b};

    // The 8-bit result is the lower 8 bits of the sum.
    assign s = sum[7:0];

    // Overflow detection for two's complement addition:
    // Overflow occurs if the carry into the MSB (bit 7) differs from the carry out of the MSB.
    // Here, carry into MSB is sum[7] (the carry out of bit 6), and carry out of MSB is sum[8].
    assign overflow = sum[7] ^ sum[8];

