Prob079_fsm3onehot.code:
module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // next_state logic (combinational)
    // Derived by inspection from the transition table with one-hot encoding:
    // A (0001) -> in=0: A (0001), in=1: B (0010)
    // B (0010) -> in=0: C (0100), in=1: B (0010)
    // C (0100) -> in=0: A (0001), in=1: D (1000)
    // D (1000) -> in=0: C (0100), in=1: B (0010)

    assign next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
                        (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
                        (state == 4'b0100) ? (in ? 4'b1000 : 4'b0001) :
                        (state == 4'b1000) ? (in ? 4'b0010 : 4'b0100) :
                        4'b0000; // default, should not occur with valid state

    // output logic (Moore machine: output depends only on current state)
    // Out = 1 when state is D (1000), else 0
    assign out = (state == 4'b1000) ? 1'b1 : 1'b0;

endmodule

