module TopModule (
    input  clk,
    input  enable,
    input  S,
    input  A,
    input  B,
    input  C,
    output Z
);

    // Internal signals for the 8-bit shift register
    reg [7:0] Q;

    // 8-bit D-type flip-flop shift register
    // Synchronous active-high enable
    always @(posedge clk) begin
        if (enable)
            Q <= {S, Q[7:1]};  // Shift-in S at MSB (Q[0]), shift rest right
        else
            Q <= Q;             // Hold state when enable is low
    end

    // 3-to-8 line decoder to select which Q output feeds Z
    // ABC selects the index: 000 -> Q[0], 001 -> Q[1], ..., 111 -> Q[7]
    wire [7:0] mux_sel;
    assign mux_sel = 8'b00000001 << {A, B, C};  // Generate select line for chosen index

    // 8-to-1 multiplexer: Z = Q[index] where index = {A,B,C}
    // Using continuous assignment with generate or generate case is synthesisable,
    // but a simple assign with conditional is also fine for 8 inputs.
    assign Z = (A & B & C) ? Q[7] :
               (A & B & ~C) ? Q[6] :
               (A & ~B & C) ? Q[5] :
               (A & ~B & ~C) ? Q[4] :
               (~A & B & C) ? Q[3] :
               (~A & B & ~C) ? Q[2] :
               (~A & ~B & C) ? Q[1] :
               (~A & ~B & ~C) ? Q[0] :
               1'bz;  // Should never happen for valid ABC

endmodule

