Prob088_ece241_2014_q5b.code:
module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    // One-hot encoded state register
    // State A: 2'b01 (bit 0 set)
    // State B: 2'b10 (bit 1 set)
    logic [1:0] state, next_state;

    // Next-state logic (Mealy FSM)
    always_comb begin
        case (state)
            2'b01: // State A
                begin
                    if (x == 1'b0) begin
                        next_state = 2'b01; // A --x=0--> A
                        z          = 1'b0;
                    end
                    else begin           // x == 1
                        next_state = 2'b10; // A --x=1--> B
                        z          = 1'b1;
                    end
                end
            2'b10: // State B
                begin
                    if (x == 1'b0) begin
                        next_state = 2'b10; // B --x=0--> B
                        z          = 1'b1;
                    end
                    else begin           // x == 1
                        next_state = 2'b10; // B --x=1--> B
                        z          = 1'b0;
                    end
                end
            default: begin
                next_state = 2'b01; // Fallback to State A
                z        = 1'b0;
            end
        endcase
    end

    // State register with asynchronous active-high reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // Reset into state A
        else
            state <= next_state;
    end

endmodule

