    input  clk,
    input  reset,
    output shift_ena
);

    // Internal state register
    reg [1:0] state;

    // Synchronous reset, active high
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            // Detect the "proper bit pattern" – here we use the
            // rising edge of the reset signal as the trigger.
            // After reset is de-asserted, shift_ena is asserted
