module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // State encoding: 2 bits
    // 2'b00: IDLE (waiting for reset release)
    // 2'b01: ACCEPTING (collecting bits, LSB first)
    // 2'b10: COMPLEMENTING (computing 2's complement)
    // 2'b11: DONE (output stable, wait for next reset)
    reg [1:0] state;
    reg [3:0] bit_count; // counts bits up to 15 (arbitrary length limit for simulation)
    reg [15:0] acc;      // accumulator for input bits (LSB first)
    reg [15:0] inv;      // bitwise inverse of accumulator
    reg [15:0] ones;     // carry-save for adding 1
    reg [15:0] comp;     // final 2's complement result

    // State transition logic (positive edge triggered, asynchronous active-high reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state    <= 2'b00;
            bit_count <= 4'b0;
            acc       <= 16'd0;
            inv       <= 16'd0;
            ones      <= 16'd0;
            comp      <= 16'd0;
        end else begin
            case (state)
                2'b00: begin // IDLE
                    // Wait for reset release
                    if (!areset) begin
                        state    <= 2'b01;
                        bit_count <= 4'd0;
                        acc       <= 16'd0;
                        inv       <= 16'd0;
                        ones      <= 16'd0;
                        comp      <= 16'd0;
                    end
                end

                2'b01: begin // ACCEPTING
                    // Accept one bit per clock cycle, LSB first
                    if (bit_count < 4'd15) begin
                        acc       <= {x, acc[15:1]};
                        bit_count <= bit_count + 1'b1;
                        // Compute inverse on the fly
                        inv       <= ~{x, inv[15:1]};
                    end else begin
                        // Last bit accepted, move to COMPLEMENTING state
                        acc       <= {x, acc[15:1]};
                        inv       <= ~{x, inv[15:1]};
                        bit_count <= bit_count + 1'b1;
                        state     <= 2'b10;
                    end
                end

                2'b10: begin // COMPLEMENTING
                    // Compute 2's complement: invert and add 1
                    // ones = inv + 1
                    ones      <= inv + 16'd1;
                    // comp = ones (the 2's complement result)
                    comp      <= ones;
                    state     <= 2'b11;
                end

                2'b11: begin // DONE
                    // Hold output stable; wait for next reset assertion
                    // State remains DONE until areset is asserted
                end
            endcase
        end
    end

    // Output assignment: z is the most significant bit of the 2's complement result
    // For arbitrary length, we output the MSB of the computed complement.
    // If the number is 0, z is 0. If the number is non-zero, z is the sign bit.
    assign z = comp[15];

endmodule

