module TopModule (
    input  [5:0] y,   // current state (one-hot)
    input        w,
    output       Y1,  // next state bit for flip-flop y[1]
    output       Y3   // next state bit for flip-flop y[3]
);

    // State encoding (one-hot):
    // y[5] = 1 -> F
    // y[4] = 1 -> E
    // y[3] = 1 -> D
    // y[2] = 1 -> C
    // y[1] = 1 -> B
    // y[0] = 1 -> A

    // Next-state logic derived by inspection of the FSM:
    // A(000001) --1--> B(000010), --0--> A
    // B(000010) --1--> C(000100), --0--> D(001000)
    // C(000100) --1--> E(010000), --0--> D
    // D(001000) --1--> F(100000), --0--> A
    // E(010000) --1--> E, --0--> D
    // F(100000) --1--> C, --0--> D

    // Y1 is the next value of flip-flop y[1] (state B)
    // From the FSM:
    //   A -> B when w=1, else A (y[1] stays 0)
    //   B -> C when w=1 (y[1] becomes 0), else B (y[1] stays 1)
    //   C -> E (y[1] becomes 0)
    //   D -> A (y[1] becomes 1)
    //   E -> E (y[1] stays 0) or D (y[1] becomes 1)
    //   F -> C (y[1] becomes 0) or D (y[1] becomes 1)
    // Collecting the next value for y[1]:
    //   next_y1 = 1 when (current state is D) OR (current state is E and w=0) OR (current state is F and w=0)
    //   next_y1 = 0 otherwise (including when in A, B, C, or F with w=1, etc.)
    assign Y1 = y[3] | (~w & y[4]) | (~w & y[5]);

    // Y3 is the next value of flip-flop y[3] (state D)
    // From the FSM:
    //   A -> A (y[3] stays 0)
    //   B -> C (y[3] becomes 0) or D (y[3] becomes 1)  -- when w=0 go to D (y[3]=1), w=1 go to C (y[3]=0)
    //   C -> D (y[3] becomes 1) regardless of w
    //   D -> F (y[3] becomes 0) or A (y[3] becomes 0)  -- both next states have y[3]=0
    //   E -> D (y[3] becomes 1) or E (y[3] stays 0)   -- when w=0 go to D (y[3]=1), w=1 stay E (y[3]=0)
    //   F -> C (y[3] becomes 0) or D (y[3] becomes 1)  -- when w=0 go to D (y[3]=1), w=1 go to C (y[3]=0)
    // Collecting the next value for y[3]:
    //   next_y3 = 1 when (current state is B and w=0) OR (current state is C) OR (current state is E and w=0) OR (current state is F and w=0)
    //   next_y3 = 0 otherwise
    assign Y3 = (y[1] & ~w) | y[2] | (~w & y[4]) | (~w & y[5]);

endmodule

