module TopModule (
    input do_sub,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out,
    output reg result_is_zero
);

    always @(*) begin
        case (do_sub)
            0: out = a + b;
            1: out = a - b;
        endcase

        // Bug fix: Use the carry-out (or borrow-out) flag from the arithmetic
        // operation instead of a simple bitwise NOT of the result.
        // For addition: carry is out[8] (implicit, but we can infer it).
        // For subtraction: borrow is ~out[8] (or we check the result sign).
        // A portable synthesis-friendly method is to check the MSB of the
        // result for signed zero, but for an unsigned zero flag we must
        // consider the overflow/borrow. Here we use a full 9-bit intermediate
        // to capture the carry/borrow, or simply rely on the fact that
        // `out == 8'h00` is the correct zero-detection logic for both
        // operations when using two's complement arithmetic.
        //
        // The original bug: `if (~out)` toggles the flag for any non-zero
        // value, including cases where the result wraps around (e.g. 0xFF - 0x01 = 0xFE
        // is correctly non-zero, but 0x00 - 0x00 = 0x00 is zero, while
        // 0x80 - 0x80 = 0x00 is also zero but might be missed if only
        // `~out` on the lower 8 bits is used without considering the
        // borrow out of bit 7). The robust fix is to compare the result
        // explicitly against zero.
        if (out == 8'h00)
            result_is_zero = 1'b1;
        else
            result_is_zero = 1'b0;
    end

endmodule

