module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out
);

    // The K-map truth table:
    //        ab
    // cd   00  01  11  10
    // 00 | 0 | 1 | 0 | 1 |
    // 01 | 1 | 0 | 1 | 0 |
    // 11 | 0 | 1 | 0 | 1 |
    // 10 | 1 | 0 | 1 | 0 |
    //
    // Simplified SOP expression: (a & b & c & d) | (a & ~b & c & d) | (~a & b & c & d) | (~a & ~b & c & d)
    // which simplifies to: c & d & (a ^ b ^ 1)  or  c & d & ~(a ^ b)
    // However, to ensure exact synthesis from the K-map without relying on
    // optimization tricks, we implement the canonical sum-of-products
    // directly from the minterms (rows where out=1):
    // Minterms: a=0,b=1,c=0,d=1  -> !a & b & !c & d
    //           a=0,b=1,c=1,d=0  -> !a & b &  c & !d
    //           a=1,b=0,c=0,d=1  ->  a & !b & !c & d
    //           a=1,b=0,c=1,d=0  ->  a & !b &  c & !d
    //           a=0,b=0,c=0,d=1  -> !a & !b & !c & d
    //           a=0,b=0,c=1,d=0  -> !a & !b &  c & !d
    //           a=1,b=1,c=0,d=1  ->  a &  b & !c & d
    //           a=1,b=1,c=1,d=0  ->  a &  b &  c & !d

    assign out = (!a &  b & !c &  d) |
                 (!a &  b &  c & !d) |
                 ( a & !b & !c &  d) |
                 ( a & !b &  c & !d) |
                 (!a & !b & !c &  d) |
                 (!a & !b &  c & !d) |
                 ( a &  b & !c &  d) |
                 ( a &  b &  c & !d);

endmodule

