module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);

    // State encoding: 0 = waiting for start byte, 1 = received byte 1, 2 = received byte 2, 3 = received byte 3
    typedef enum logic [1:0] {
        IDLE      = 2'b00,
        BYTE1     = 2'b01,
        BYTE2     = 2'b10,
        BYTE3     = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            IDLE: begin
                // Wait until in[3] is high
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = IDLE;
            end
            BYTE1: begin
                // Received first byte (in[3]=1), move to byte 2
                next_state = BYTE2;
            end
            BYTE2: begin
                // Received second byte, move to byte 3
                next_state = BYTE3;
            end
            BYTE3: begin
                // Received third byte, signal done in the next cycle
                // We stay in BYTE3 for one cycle then return to IDLE,
                // but 'done' is pulsed high in the cycle after reception.
                // To achieve "done in the cycle immediately after the third byte",
                // we assert done here and transition to IDLE next cycle.
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic: done is pulsed high exactly one cycle after the third byte is latched.
    // Since the FSM transitions from BYTE3 to IDLE on the same clock edge
    // where the third byte is sampled, we assert 'done' when we enter IDLE
    // from BYTE3. However, the specification requires done to be signalled
    // "in the cycle immediately after the third byte of each message was
    //  successfully received". 
    // We accomplish this by setting done high in the cycle following the
    // transition out of BYTE3. Since the state update happens on the posedge,
    // if we are in BYTE3 and next_state becomes IDLE, the 'done' pulse
    // occurs in the cycle after the posedge that captured the third byte.
    // To make this explicit and avoid glitches, we use a registered output.

    // Registered done signal
    always_ff @(posedge clk) begin
        if (reset)
            done <= 1'b0;
        else if (state == BYTE3 && next_state == IDLE)
            done <= 1'b1;  // Pulse done in the cycle after third byte received
        else
            done <= 1'b0;  // Clear done in all other cases
    end

endmodule

