module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE      = 3'b000,
        START     = 3'b001,
        DATA      = 3'b010,
        STOP      = 3'b011,
        WAIT_STOP = 3'b100
    } state_t;

    state_t state, next_state;

    // Counters and shift register
    logic [3:0] bit_cnt;   // 0 to 8 (8 data bits)
    logic [7:0] shift_reg;

    // FSM state transition logic (positive edge triggered, synchronous reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            bit_cnt   <= 4'd0;
            shift_reg <= 8'd0;
            done      <= 1'b0;
            out_byte  <= 8'd0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    if (in == 1'b0) begin // start bit detected (falling edge)
                        next_state <= START;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                START: begin
                    // Wait for the middle of the start bit to ensure it was valid
                    if (in == 1'b1) begin
                        next_state <= DATA;
                        bit_cnt      <= 4'd0;
                        shift_reg    <= 8'd0;
                    end else begin
                        next_state <= START; // hold until sample point
                    end
                end

                DATA: begin
                    // Shift in data bit (LSB first)
                    shift_reg <= {in, shift_reg[7:1]};
                    bit_cnt   <= bit_cnt + 4'd1;

                    if (bit_cnt == 4'd7) begin // have received 8 data bits (bits 0-7)
                        next_state <= STOP;
                    end else begin
                        next_state <= DATA;
                    end
                end

                STOP: begin
                    // Verify stop bit is 1
                    if (in == 1'b1) begin
                        next_state <= WAIT_STOP;
                        out_byte   <= shift_reg;
                        done       <= 1'b1;
                    end else begin
                        // Stop bit not correct: go back to IDLE to wait for next start bit
                        // The current byte is discarded; done is not asserted
                        next_state <= IDLE;
                    end
                end

                WAIT_STOP: begin
                    // Idle state after successful byte reception.
                    // Remain here until a new start bit is detected.
                    if (in == 1'b0) begin
                        next_state <= START;
                    end else begin
                        next_state <= WAIT_STOP;
                    end
                end

                default: next_state <= IDLE;
            endcase
        end
    end

endmodule

