    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 2 bits
    // 2'b00: WALKING_LEFT
    // 2'b01: WALKING_RIGHT
    // 2'b10: FALLING
    // 2'b11: DIGGING
    reg [1:0] state, next_state;

    // State register (positive edge triggered, async reset)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b00;  // walk_left
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always @(*) begin
        // Default: keep current state
        next_state = state;

        case (state)
            2'b00: begin // WALKING_LEFT
                if (!ground) begin
                    // Fall has higher precedence than dig or direction switch
                    next_state = 2'b10; // FALLING
                end else if (dig) begin
                    // Can dig while walking on ground
                    next_state = 2'b11; // DIGGING
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped (both sides switches too)
                    if (bump_left && !bump_right)
                        next_state = 2'b01; // WALKING_RIGHT
                    else if (bump_right && !bump_left)
                        next_state = 2'b00; // WALKING_LEFT
                    // If both bumped, state stays WALKING_LEFT (already facing left)
                end
                // else stay in WALKING_LEFT
            end

            2'b01: begin // WALKING_RIGHT
                if (!ground) begin
                    next_state = 2'b10; // FALLING
                end else if (dig) begin
                    next_state = 2'b11; // DIGGING
