module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state
    logic [511:0] q_reg;

    // Combinational logic: compute next state based on Rule 110
    // Boundaries are treated as 0 (off)
    always_comb begin
        logic [511:0] next_q;

        // Cell 0: Left is 0, Center is q_reg[0], Right is q_reg[1]
        next_q[0] = (~q_reg[0] & q_reg[1]) | (1'b0 & q_reg[0] & q_reg[1]) | (1'b0 & q_reg[0] & ~q_reg[1]);
        // Simplified: (~q_reg[0] & q_reg[1]) because left=0 eliminates other terms

        // Cells 1 to 510
        for (int i = 1; i < 511; i = i + 1) begin
            // Left = q_reg[i-1], Center = q_reg[i], Right = q_reg[i+1]
            next_q[i] = (q_reg[i-1] & ~q_reg[i] & q_reg[i+1]) | 
                        (~q_reg[i-1] & q_reg[i] & q_reg[i+1]) | 
                        (~q_reg[i-1] & q_reg[i] & ~q_reg[i+1]);
        end

        // Cell 511: Left is q_reg[510], Center is q_reg[511], Right is 0
        next_q[511] = (q_reg[510] & ~q_reg[511] & 1'b0) | 
                      (~q_reg[510] & q_reg[511] & 1'b0) | 
                      (~q_reg[510] & q_reg[511] & ~1'b0);
        // Simplified: (~q_reg[510] & q_reg[511]) because right=0 eliminates other terms

        // Drive the output q with the computed next state
        q = next_q;
    end

    // Sequential logic: register update
    always_ff @(posedge clk) begin
        if (load) begin
            q_reg <= data;
        end else begin
            q_reg <= q;
        end
    end

endmodule

