module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // State encoding: 4 bits are sufficient for the 7 defined states
    typedef enum logic [3:0] {
        IDLE      = 4'b0000,  // Waiting for start bit
        START     = 4'b0001,  // Detected start bit, sampling data bits
        DATA0     = 4'b0010,  // Receiving data bit 0 (LSB)
        DATA1     = 4'b0011,  // Receiving data bit 1
        DATA2     = 4'b0100,  // Receiving data bit 2
        DATA3     = 4'b0101,  // Receiving data bit 3
        DATA4     = 4'b0110,  // Receiving data bit 4
        DATA5     = 4'b0111,  // Receiving data bit 5
        DATA6     = 4'b1000,  // Receiving data bit 6
        DATA7     = 4'b1001,  // Receiving data bit 7 (MSB)
        STOP      = 4'b1010,  // Verifying stop bit
        ERROR     = 4'b1011   // Stop bit mismatch; wait for next start
    } state_t;

    // State register with synchronous active-high reset
    state_t state, next_state;

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Output logic: 'done' goes high for one clock cycle after a valid byte is received
    assign done = (state == STOP) && (next_state == IDLE);

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;  // Default: stay in current state

        case (state)
            IDLE: begin
                // Idle until a falling edge (start bit = 0) is detected
                if (~in)
                    next_state = START;
                else
                    next_state = IDLE;
            end

            START: begin
                // After detecting start bit (0), shift in data bits LSB first.
                // We sample the data bits on the next 8 clock edges.
                next_state = DATA0;
            end

            DATA0: begin
                // Receive bit 0 (LSB). Always sample 'in'.
                next_state = DATA1;
            end

            DATA1: begin
                next_state = DATA2;
            end

            DATA2: begin
                next_state = DATA3;
            end

            DATA3: begin
                next_state = DATA4;
            end

            DATA4: begin
                next_state = DATA5;
            end

            DATA5: begin
                next_state = DATA6;
            end

            DATA6: begin
                next_state = DATA7;
            end

            DATA7: begin
                // After receiving the 8th bit (MSB), check the stop bit on the next clock.
                // If stop bit is 1, transition to STOP; otherwise go to ERROR.
                if (in)
                    next_state = STOP;
                else
                    next_state = ERROR;
            end

            STOP: begin
                // Stop bit verified as 1. Pulse 'done' high for one cycle,
                // then return to IDLE to wait for the next byte.
                next_state = IDLE;
            end

            ERROR: begin
                // Stop bit was not 1 when expected.
                // Wait until a new start bit (falling edge) appears.
                if (~in)
                    next_state = ERROR;  // Keep sampling; stay in ERROR
                else
                    next_state = IDLE;   // Idle line detected; ready for next byte
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

