                    y_next = 1'b0; // A
            end
            3'b100: begin // State E
                // E(1)-->E(100) if w=0, E(1)-->D(011) if w=1
                // y[1] next = 1 always (E has y[1]=1, D has y[1]=1)
                y_next = 1'b1; // E
            end
            3'b101: begin // State F
                // F(1)-->C(010) if w=0, F(1)-->D(011) if w=1
                // y[1] next = 0 if w=0 (C=010), 1 if w=1 (D=011)
                if (w == 1'b0)
                    y_next = 1'b0; // C
                else
                    y_next = 1'b1; // D
            end
            default: y_next = 1'b0; // undefined state
        endcase
    end

endmodule

